# Same observer family, two independently optimized objectives, three scales
comparison=[]
for q_i,r_i in [(1.,.25),(1.,1.),(.25,1.)]:
    L_h=-q_i/(r_i*a);L_k=a+np.sqrt(a*a+q_i/r_i)
    row={'q':q_i,'r':r_i}
    for name,gain in [('Hinf',L_h),('Kalman',L_k),('noCorrection',0.)]:
        noise=q_i+r_i*gain*gain;lam=gain-a
        row[name]={'gain':gain,'peak':float(np.sqrt(noise)/lam),'variance':noise/(2*lam)}
    comparison.append(row);print(row)
print('a=0 q=1 r=.25: infimum=.5, no finite minimizer')
for gain in [1.,4.,100.]:print('integrator gain=',gain,'exact peak=',np.sqrt(1+.25*gain**2)/gain)
print('a=1 L=.5: error pole=+.5, no stable Hinf norm or stationary variance')
for dt in [.02,.4,.5]:
    factor=1-dt*5;print('Euler dt=',dt,'factor=',factor,'strict stable=',abs(factor)<1,'exact ZOH factor=',np.exp(-5*dt))
gains=np.linspace(0,8,401);fig,ax=plt.subplots(1,2,figsize=(10,3.5))
ax[0].plot(gains,np.sqrt(1+.25*gains*gains)/(gains+1));ax[0].set(xlabel='L',ylabel='worst energy gain')
ax[1].plot(gains,(1+.25*gains*gains)/(2*(gains+1)));ax[1].set(xlabel='L',ylabel='stationary white-noise variance');plt.tight_layout();plt.show()
print('comparison_and_digital_complete')
